    font-family: monospace;
    font-size: 8pt;
    height: 140px;
    overflow: auto;
    padding: 3px;
}

a:not([class]):not([id]){/* Plain link */
text-decoration:underline;
}
a.new,
#WikiHeader a{/* Redlink */
opacity:0.75;
text-decoration:none;
}


#MonoBookWarning{
border:2px solid #800;
border-radius:2mm;
}



#WikiaMainContent{
width: 100%;
/*width:7in;*/
z-index: 1;
}
#WikiaRail{
margin-top: 1cm;
opacity:0.25;
opacity:1;
overflow: hidden;
position: absolute;
right: 0;
width:1cm;
width:3.1in;
z-index: 2;

transition-property: opacity, width;
transition-duration: 0.25s, 0.5s;
transition-timing-function: ease-out;
transition-delay: 0s, 0.5s;

-o-transition-property: opacity, width;
-o-transition-duration: 0.25s, 0.5s;
-o-transition-timing-function: ease-out;
-o-transition-delay: 0s, 0.5s;

-ms-transition-property: opacity, width;
-ms-transition-duration: 0.25s, 0.5s;
-ms-transition-timing-function: ease-out;
-ms-transition-delay: 0s, 0.5s;

-moz-transition-property: opacity, width;
-moz-transition-duration: 0.25s, 0.5s;
-moz-transition-timing-function: ease-out;
-moz-transition-delay: 0s, 0.5s;

-webkit-transition-property: opacity, width;
-webkit-transition-duration: 0.25s, 0.5s;
-webkit-transition-timing-function: ease-out;
-webkit-transition-delay: 0s, 0.5s;
}
#WikiaRail:hover{
width:3.2in;
opacity:1;
}
#WikiaRail #WikiaSearch{
width:3in;
}
#WikiaRail #WikiaSearch input[type=text]{
width:auto;
}
#WikiaRail #WikiaSearch button{
display:none;
}
#WikiaRail:hover #WikiaSearch button{
display:block;
}
#WikiaRail .module{
overflow:hidden;
width:3in;
}



