background: -ms-linear-gradient(red, #800) !important;     background: -ms-linear-gradient(red, var(light-redstoneRed)) !important;     background: -ms-linear-gradient(red, lightSkin.redstoneRed) !important;
background: -moz-linear-gradient(red, #800) !important;    background: -moz-linear-gradient(red, var(light-redstoneRed)) !important;    background: -moz-linear-gradient(red, lightSkin.redstoneRed) !important;
background: -webkit-linear-gradient(red, #800) !important; background: -webkit-linear-gradient(red, var(light-redstoneRed)) !important; background: -webkit-linear-gradient(red, lightSkin.redstoneRed) !important;
border: .5mm solid #800 !important; border-color:var(light-redstoneRed) !important; border-color:lightSkin.redstoneRed !important;
border-radius: 1.5mm !important;
color: white !important;
padding: 0.5mm 1mm 0.5mm 0.5mm !important;
}
.thumbimage{
border: .5mm solid #800 !important; border-color:var(light-redstoneRed) !important; border-color:lightSkin.redstoneRed !important;
